import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { Button, Pagination, TableCard } from '@linm-soft-org/linm-web-common-components';
import { scykRoutes } from '../../config/scykRoutes';
import { incidentPublicReportService } from '../../services/incidentPublicReports';
import type { IncidentPublicReport, IncidentPublicReportGuestInit } from '../../models/IncidentPublicReport';
import { getApiErrorMessage } from '../../utils/apiMessages';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { getOrCreatePublicDeviceId } from '../../utils/publicDeviceId';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import { PublicReportTable } from '../IncidentPublicReportListPage/components/PublicReportTable';
import guestStyles from '../IncidentPublicReportGuestPage/IncidentPublicReportGuestPage.module.css';
import listStyles from '../IncidentDetectionListPage/IncidentDetectionListPage.module.css';

const IncidentPublicReportGuestListPage: React.FC = () => {
  const { companyCode = '' } = useParams<{ companyCode: string }>();
  const appNavigate = useAppNavigate();
  const [init, setInit] = useState<IncidentPublicReportGuestInit | null>(null);
  const [items, setItems] = useState<IncidentPublicReport[]>([]);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const showLoading = useMinLoadingTime(loading);
  const L = (key: string) => init?.labels.find((o) => o.value === key)?.label ?? key;
  const statusLabel = (status: string) =>
    init?.statuses.find((o) => o.value === status)?.label ?? status;

  useEffect(() => {
    getOrCreatePublicDeviceId();
  }, []);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    const t = setTimeout(() => {
      Promise.all([
        incidentPublicReportService.guestInit(companyCode),
        incidentPublicReportService.mine(companyCode, page, 20),
      ])
        .then(([initData, list]) => {
          if (cancelled) return;
          setInit(initData);
          setItems(list.items);
          setTotal(list.total);
        })
        .catch((err) => { if (!cancelled) setError(getApiErrorMessage(err)); })
        .finally(() => { if (!cancelled) setLoading(false); });
    }, 0);
    return () => { cancelled = true; clearTimeout(t); };
  }, [companyCode, page]);

  return (
    <div className={guestStyles.page} data-testid="incident-public-report-guest-list">
      <div className={guestStyles.header}>
        <div className={guestStyles.brand}>
          <h1>{L('historyTitle')}</h1>
          <p>{init?.companyName}</p>
        </div>
      </div>
      <div className={guestStyles.formBody}>
        {error && <div className={guestStyles.errorBanner}>{error}</div>}
        <div className={listStyles.headerActions}>
          <Button variant="secondary" onClick={() => appNavigate(scykRoutes.publicReports.guest(companyCode))}>
            {L('back')}
          </Button>
        </div>
        <TableCard
          footer={
            <Pagination
              currentPage={page}
              totalPages={Math.ceil(Math.max(total, 1) / 20)}
              totalCount={total}
              pageSize={20}
              onPageChange={setPage}
            />
          }
        >
          <PublicReportTable
            items={items}
            loading={showLoading}
            guest
            onView={(item) => appNavigate(scykRoutes.publicReports.guestView(companyCode, item.id))}
            label={L}
            statusLabel={statusLabel}
          />
        </TableCard>
      </div>
    </div>
  );
};

export default IncidentPublicReportGuestListPage;
